1	"use client";
2	
3	/**
4	 * PREVIEW TEMPLATE — "AI / vibe-coding hosting".
5	 *
6	 * The most modern page on the site: a Claude-powered "Build with AI" builder
7	 * that also hosts. The hero centerpiece is a genuinely-animated
8	 * describe → build → deploy → live flow (a chat prompt types, Claude streams
9	 * build steps that check off, a deploy terminal resolves to "Live in 47s", and
10	 * a light browser frame assembles the built site). A second wedge lets you
11	 * import an app you already vibe-coded elsewhere (Bolt / Lovable / v0 / Cursor)
12	 * and host it. Asymmetric, editorial, motion-forward — never a centered stack.
13	 *
14	 * Net-new, preview-only. Touches no live page or shared component.
15	 */
16	
17	import Link from "next/link";
18	import { useEffect, useRef, useState, type ReactNode } from "react";
19	import styles from "./aihosting.module.css";
20	import { usePrefersReducedMotion, useInViewOnce, StarRow, LiveDot } from "./kit";
21	import { ReasonIcon } from "./icons-map";
22	import {
23	  BUILD_PROMPT,
24	  BUILD_STEPS,
25	  DEPLOY_STEPS,
26	  IMPORT_SOURCES,
27	  REASONS,
28	  PLANS,
29	  REVIEWS,
30	  RATING_LABEL,
31	} from "./data";
32	import { ClaudeMark } from "@/components/marketing/ClaudeMark";
33	import { IconCheck, IconArrow, IconBolt } from "@/components/marketing/icons";
34	
35	/* ── Hero centerpiece: describe → build → deploy → live ──────────────────── */
36	function BuildConsole() {
37	  const reduced = usePrefersReducedMotion();
38	  const { ref, seen } = useInViewOnce<HTMLDivElement>();
39	  const [typed, setTyped] = useState("");
40	  const [phase, setPhase] = useState<"idle" | "typing" | "building" | "deploying" | "live">("idle");
41	  const [built, setBuilt] = useState(0);
42	  const [deployed, setDeployed] = useState(0);
43	  const timers = useRef<ReturnType<typeof setTimeout>[]>([]);
44	
45	  useEffect(() => {
46	    if (!seen) return;
47	    if (reduced) {
48	      setTyped(BUILD_PROMPT);
49	      setBuilt(BUILD_STEPS.length);
50	      setDeployed(DEPLOY_STEPS.length);
51	      setPhase("live");
52	      return;
53	    }
54	    let dead = false;
55	    const push = (fn: () => void, ms: number) => {
56	      if (!dead) timers.current.push(setTimeout(fn, ms));
57	    };
58	    const run = () => {
59	      setTyped("");
60	      setBuilt(0);
61	      setDeployed(0);
62	      setPhase("typing");
63	      const charMs = 34;
64	      BUILD_PROMPT.split("").forEach((_, i) => push(() => setTyped(BUILD_PROMPT.slice(0, i + 1)), 300 + charMs * i));
65	      const afterType = 300 + charMs * BUILD_PROMPT.length + 500;
66	      push(() => setPhase("building"), afterType);
67	      BUILD_STEPS.forEach((_, i) => push(() => setBuilt(i + 1), afterType + 720 * (i + 1)));
68	      const afterBuild = afterType + 720 * (BUILD_STEPS.length + 1);
69	      push(() => setPhase("deploying"), afterBuild);
70	      DEPLOY_STEPS.forEach((_, i) => push(() => setDeployed(i + 1), afterBuild + 640 * (i + 1)));
71	      const afterDeploy = afterBuild + 640 * (DEPLOY_STEPS.length + 1);
72	      push(() => setPhase("live"), afterDeploy);
73	      push(run, afterDeploy + 5200); // loop
74	    };
75	    run();
76	    return () => {
77	      dead = true;
78	      timers.current.forEach(clearTimeout);
79	      timers.current = [];
80	    };
81	  }, [seen, reduced]);
82	
83	  const showSite = phase === "live";
84	  // Visibility, not mounting: every block below is ALWAYS in the DOM and only
85	  // fades in/out, so the console's layout box is fixed and the page never
86	  // reflows as the animation runs (see Task 1 — stable hero container).
87	  const showBuild = phase === "building" || phase === "deploying" || phase === "live";
88	  const showDeploy = phase === "deploying" || phase === "live";
89	
90	  return (
91	    <div ref={ref} className={reduced ? "" : "pv-float-slow"}>
92	      <div className="relative grid gap-4 sm:grid-cols-[1.05fr_0.95fr] sm:items-start">
93	        {/* Ambient glow behind the console. Deliberately much larger than the
94	            console (-inset-28) with same-hue alpha-0 stops and a heavy blur, so
95	            the light reaches full transparency well before the element's own box
96	            edge — it reads as ambient light bleeding into the page, never as a
97	            lit rectangle with a hard cutoff. */}
98	        <div
99	          className="pointer-events-none absolute -inset-28 -z-10"
100	          style={{
101	            background:
102	              "radial-gradient(50% 50% at 22% 14%, rgba(59,130,246,0.26), rgba(59,130,246,0) 66%), radial-gradient(52% 52% at 88% 92%, rgba(138,112,251,0.28), rgba(138,112,251,0) 66%)",
103	            filter: "blur(44px)",
104	          }}
105	          aria-hidden
106	        />
107	
108	        {/* Claude chat / build panel */}
109	        <div className="relative overflow-hidden rounded-2xl border border-white/10 bg-[#080d18]/90 shadow-2xl shadow-black/50 backdrop-blur-xl">
110	          <div className="flex items-center gap-2 border-b border-white/[0.06] bg-white/[0.02] px-4 py-2.5">
111	            <span className="flex h-6 w-6 items-center justify-center rounded-md bg-gradient-to-br from-accent-blue to-brand-500 text-white">
112	              <ClaudeMark size={13} />
113	            </span>
114	            <span className="text-[12px] font-medium text-slate-300">Claude · connected to your server</span>
115	            <span className="ml-auto inline-flex items-center gap-1.5 rounded-full bg-emerald-500/12 px-2 py-0.5 text-[10px] font-medium text-emerald-300">
116	              <span className="h-1.5 w-1.5 rounded-full bg-emerald-400 motion-safe:animate-pulse-dot" />
117	              live
118	            </span>
119	          </div>
120	
121	          <div className="space-y-3 px-4 py-4 text-[13px] leading-relaxed">
122	            {/* User prompt (typing). An invisible copy of the FULL prompt sets
123	                the bubble's final wrapped height at any width; the typed text is
124	                overlaid on top, so the bubble never grows line-by-line as it
125	                types (no reflow). */}
126	            <div className="relative ml-auto max-w-[88%] rounded-2xl rounded-br-sm border border-brand-500/25 bg-brand-500/10 px-3.5 py-2.5 text-slate-100">
127	              <span className="invisible" aria-hidden>
128	                {BUILD_PROMPT}
129	              </span>
130	              <span className="absolute inset-0 px-3.5 py-2.5">
131	                {typed || <span className="text-slate-500">Describe what you want to build…</span>}
132	                {phase === "typing" && (
133	                  <span className="ml-0.5 inline-block h-3.5 w-1.5 translate-y-[2px] bg-brand-300 motion-safe:animate-blink" />
134	                )}
135	              </span>
136	            </div>
137	
138	            {/* Claude building. Always mounted — space is reserved from first
139	                paint and only opacity animates, so the panel height is fixed. */}
140	            <div
141	              className={`max-w-[94%] rounded-2xl rounded-bl-sm border border-white/[0.07] bg-white/[0.03] px-3.5 py-3 motion-safe:transition-opacity motion-safe:duration-500 ${
142	                showBuild ? "opacity-100" : "opacity-0"
143	              }`}
144	              aria-hidden={!showBuild}
145	            >
146	              <p className="text-slate-300">On it — here&apos;s the plan:</p>
147	              <ul className="mt-2.5 space-y-1.5 font-mono text-[12px]">
148	                {BUILD_STEPS.map((s, i) => {
149	                  const done = built > i;
150	                  return (
151	                    <li key={s.label} className={`flex items-center gap-2 ${done ? "text-slate-300" : "text-slate-600"}`}>
152	                      <span
153	                        className={`flex h-3.5 w-3.5 shrink-0 items-center justify-center rounded-full ${
154	                          done ? "bg-emerald-500/15 text-emerald-400" : "border border-white/10 text-transparent"
155	                        }`}
156	                      >
157	                        <IconCheck size={10} />
158	                      </span>
159	                      <span className="flex-1">{s.label}</span>
160	                      <span className="text-slate-600">{s.detail}</span>
161	                    </li>
162	                  );
163	                })}
164	              </ul>
165	
166	              {/* review-before-ship gate (honesty) — always mounted, fades in */}
167	              <div
168	                className={`mt-3 flex items-center gap-2 rounded-lg border border-brand-500/25 bg-brand-500/[0.08] px-2.5 py-1.5 text-[11px] text-brand-200 motion-safe:transition-opacity motion-safe:duration-500 ${
169	                  showDeploy ? "opacity-100" : "opacity-0"
170	                }`}
171	              >
172	                <IconCheck size={12} />
173	                You reviewed the plan and approved it
174	              </div>
175	
176	              {/* deploy stream — every line always mounted (reserving its full
177	                  height); lines reveal by opacity as `deployed` advances */}
178	              <div className="mt-2.5 space-y-0.5 font-mono text-[11.5px]">
179	                {DEPLOY_STEPS.map((l, i) => {
180	                  const ok = l.startsWith("✓");
181	                  const shown = showDeploy && deployed > i;
182	                  return (
183	                    <div
184	                      key={i}
185	                      className={`motion-safe:transition-opacity motion-safe:duration-300 ${shown ? "opacity-100" : "opacity-0"} ${
186	                        ok ? "font-semibold text-emerald-300" : "text-slate-400"
187	                      }`}
188	                    >
189	                      {l}
190	                    </div>
191	                  );
192	                })}
193	              </div>
194	            </div>
195	          </div>
196	
197	          <div className="border-t border-white/[0.06] px-4 py-3">
198	            <div className="flex items-center gap-2 rounded-xl border border-white/10 bg-white/[0.03] px-3 py-2 text-[12px] text-slate-500">
199	              Ask Claude to build or change anything
200	              <span className="inline-block h-3.5 w-1.5 bg-slate-500 motion-safe:animate-blink" />
201	              <span className="ml-auto flex h-6 w-6 items-center justify-center rounded-lg bg-gradient-to-br from-accent-blue to-brand-500 text-white">
202	                <ClaudeMark size={12} />
203	              </span>
204	            </div>
205	          </div>
206	        </div>
207	
208	        {/* result: assembling browser preview (light, for contrast pop) */}
209	        <div className="relative">
210	          <div className="overflow-hidden rounded-2xl border border-white/10 bg-white shadow-2xl shadow-black/40">
211	            <div className="flex items-center gap-2 border-b border-black/10 bg-slate-100 px-3 py-2">
212	              <span className="h-2.5 w-2.5 rounded-full bg-[#ff5f57]" />
213	              <span className="h-2.5 w-2.5 rounded-full bg-[#febc2e]" />
214	              <span className="h-2.5 w-2.5 rounded-full bg-[#28c840]" />
215	              <span className="ml-2 flex-1 truncate rounded-md bg-white px-2.5 py-1 text-[10px] text-slate-500 ring-1 ring-black/5">
216	                {showSite ? "https://lumen-salon.nxeon.app" : "building…"}
217	              </span>
218	            </div>
219	            <div className="relative min-h-[248px] bg-gradient-to-b from-[#faf7f2] to-white">
220	              {!showSite ? (
221	                <div className="flex min-h-[248px] flex-col items-center justify-center gap-3 px-6 text-center">
222	                  <span className="flex h-9 w-9 items-center justify-center rounded-full border-2 border-brand-500/30 border-t-brand-500 motion-safe:animate-orbit-spin" />
223	                  <p className="text-[12px] font-medium text-slate-400">Your site is assembling…</p>
224	                </div>
225	              ) : (
226	                <div className="px-4 py-3">
227	                  <div className={`flex items-center justify-between ${reduced ? "" : styles.rise}`} style={{ animationDelay: "0ms" }}>
228	                    <span className="text-[13px] font-bold tracking-tight text-emerald-800">Lumen Salon</span>
229	                    <div className="hidden gap-2 text-[9px] text-slate-500 sm:flex">
230	                      <span>Services</span>
231	                      <span>Gallery</span>
232	                      <span className="rounded-full bg-emerald-700 px-2 py-0.5 text-white">Book</span>
233	                    </div>
234	                  </div>
235	                  <div className={`mt-3 text-center ${reduced ? "" : styles.rise}`} style={{ animationDelay: "90ms" }}>
236	                    <p className="text-[9px] font-semibold uppercase tracking-[0.2em] text-emerald-700">Wellness &amp; calm</p>
237	                    <h4 className="mt-1 text-base font-bold leading-tight text-slate-800">
238	                      Relax, restore, <span className="text-emerald-700">renew.</span>
239	                    </h4>
240	                    <span className="mt-2 inline-block rounded-full bg-emerald-700 px-3 py-1 text-[10px] font-semibold text-white">
241	                      Book an appointment
242	                    </span>
243	                  </div>
244	                  <div className="mt-3 grid grid-cols-3 gap-2">
245	                    {["Massage", "Facials", "Sauna"].map((s, i) => (
246	                      <div
247	                        key={s}
248	                        className={`rounded-lg bg-white p-2 text-left shadow-sm ring-1 ring-black/5 ${reduced ? "" : styles.rise}`}
249	                        style={{ animationDelay: `${180 + i * 90}ms` }}
250	                      >
251	                        <div className="mb-1.5 h-6 rounded bg-emerald-100" />
252	                        <p className="text-[9px] font-semibold text-slate-700">{s}</p>
253	                        <p className="text-[8px] text-slate-400">from $60</p>
254	                      </div>
255	                    ))}
256	                  </div>
257	                </div>
258	              )}
259	            </div>
260	          </div>
261	          {/* live tag under the browser */}
262	          <div className="mt-3 inline-flex items-center gap-2 rounded-full border border-white/10 bg-white/[0.04] px-3 py-1.5 text-[12px] text-slate-300 backdrop-blur-md">
263	            <LiveDot />
264	            {showSite ? (
265	              <>
266	                <span className="font-semibold text-accent-cyan">Live</span> · HTTPS issued · 47s from prompt
267	              </>
268	            ) : (
269	              <>Deploying to your server…</>
270	            )}
271	          </div>
272	        </div>
273	      </div>
274	    </div>
275	  );
276	}
277	
278	/* ── Import wedge terminal (auto-cycles through sources) ──────────────────── */
279	function ImportShowcase() {
280	  const reduced = usePrefersReducedMotion();
281	  const { ref, seen } = useInViewOnce<HTMLDivElement>();
282	  const [active, setActive] = useState(0);
283	
284	  useEffect(() => {
285	    if (!seen || reduced) return;
286	    const id = window.setInterval(() => {
287	      if (document.hidden) return;
288	      setActive((a) => (a + 1) % IMPORT_SOURCES.length);
289	    }, 3400);
290	    return () => window.clearInterval(id);
291	  }, [seen, reduced]);
292	
293	  const src = IMPORT_SOURCES[active];
294	  const lines = [
295	    { t: `$ nxeon import ./my-app --from ${src.id}`, cls: "text-slate-200" },
296	    { t: `→ detected  ${src.detects}`, cls: "text-slate-400" },
297	    { t: "→ installing dependencies …… ok", cls: "text-slate-400" },
298	    { t: "→ building & issuing HTTPS …… ok", cls: "text-slate-400" },
299	    { t: "✓ deployed — my-app.nxeon.app", cls: "font-semibold text-emerald-300" },
300	  ];
301	
302	  return (
303	    <div ref={ref} className="grid gap-8 lg:grid-cols-2 lg:items-center lg:gap-12">
304	      {/* copy + source chips */}
305	      <div>
306	        <span className="eyebrow">Already built it elsewhere?</span>
307	        <h2 className="mt-3 text-3xl font-bold tracking-tight text-white sm:text-4xl">
308	          Import your <span className="grad-text">Bolt, Lovable, v0 or Cursor</span> app — and host it here
309	        </h2>
310	        <p className="mt-4 max-w-md text-lg leading-relaxed text-slate-400">
311	          Vibe-coded a prototype somewhere else? Bring the project over. We detect the framework, build it, and put it
312	          live on your own server — with full root and no lock-in.
313	        </p>
314	        <div className="mt-6 flex flex-wrap gap-2.5">
315	          {IMPORT_SOURCES.map((s, i) => (
316	            <button
317	              key={s.id}
318	              type="button"
319	              onClick={() => setActive(i)}
320	              aria-pressed={i === active}
321	              className={`inline-flex items-center gap-2 rounded-xl border px-3.5 py-2 text-sm font-medium transition-all ${
322	                i === active
323	                  ? "border-transparent bg-white/[0.06] text-white"
324	                  : "border-white/10 bg-white/[0.02] text-slate-400 hover:border-white/20 hover:text-slate-200"
325	              }`}
326	              style={i === active ? { boxShadow: `0 0 0 1px ${s.accent}66, 0 12px 30px -16px ${s.accent}` } : undefined}
327	            >
328	              <span className="flex h-6 w-6 items-center justify-center overflow-hidden rounded-md bg-white p-[3px] ring-1 ring-black/10">
329	                <img
330	                  src={`/logos/${s.logo}.svg`}
331	                  alt=""
332	                  aria-hidden="true"
333	                  loading="lazy"
334	                  decoding="async"
335	                  className="h-full w-full object-contain"
336	                />
337	              </span>
338	              {s.name}
339	            </button>
340	          ))}
341	        </div>
342	        <Link href="/register" className="btn-primary mt-7 inline-flex px-6 py-3 text-base">
343	          Import a project
344	          <IconArrow size={16} />
345	        </Link>
346	      </div>
347	
348	      {/* terminal */}
349	      <div className="relative overflow-hidden rounded-2xl border border-white/10 bg-black/60 shadow-2xl backdrop-blur-sm">
350	        <div
351	          className="pointer-events-none absolute -inset-16 -z-10"
352	          style={{
353	            background: `radial-gradient(50% 50% at 85% 0%, ${src.accent}33, ${src.accent}00 72%)`,
354	            filter: "blur(30px)",
355	          }}
356	          aria-hidden
357	        />
358	        <div className="flex items-center gap-1.5 border-b border-white/[0.06] px-4 py-2.5">
359	          <span className="h-2.5 w-2.5 rounded-full bg-red-500/70" />
360	          <span className="h-2.5 w-2.5 rounded-full bg-amber-400/70" />
361	          <span className="h-2.5 w-2.5 rounded-full bg-emerald-400/70" />
362	          <span className="ml-2 font-mono text-[11px] uppercase tracking-widest text-slate-500">nxeon · import</span>
363	          <span
364	            className="ml-auto inline-flex items-center gap-1.5 rounded-md border px-2 py-0.5 font-mono text-[10px]"
365	            style={{ borderColor: `${src.accent}55`, color: src.accent }}
366	          >
367	            from {src.name}
368	          </span>
369	        </div>
370	        {/* keyed on `active` so switching source replays the line-in reveal */}
371	        <div key={active} className="min-h-[168px] space-y-1.5 p-4 font-mono text-[12.5px] leading-relaxed">
372	          {lines.map((l, i) => (
373	            <div
374	              key={i}
375	              className={`${l.cls} ${reduced ? "" : "motion-safe:animate-line-in"}`}
376	              style={{ animationDelay: `${i * 260}ms` }}
377	            >
378	              {l.t}
379	            </div>
380	          ))}
381	        </div>
382	      </div>
383	    </div>
384	  );
385	}
386	
387	/* ── Stack ribbon (marquee of things you can build/host) ─────────────────── */
388	const STACK = [
389	  "Next.js",
390	  "React",
391	  "Vite",
392	  "Node",
393	  "Postgres",
394	  "Python",
395	  "Astro",
396	  "Express",
397	  "Prisma",
398	  "Tailwind",
399	  "SvelteKit",
400	  "Remix",
401	];
402	function StackRibbon() {
403	  return (
404	    <div className={`${styles.marquee} relative overflow-hidden`}>
405	      {/* edge fades */}
406	      <div className="pointer-events-none absolute inset-y-0 left-0 z-10 w-24 bg-gradient-to-r from-navy-950 to-transparent" aria-hidden />
407	      <div className="pointer-events-none absolute inset-y-0 right-0 z-10 w-24 bg-gradient-to-l from-navy-950 to-transparent" aria-hidden />
408	      <div className={styles.marqueeTrack} aria-hidden>
409	        {[...STACK, ...STACK].map((t, i) => (
410	          <span
411	            key={i}
412	            className="mx-1.5 shrink-0 rounded-full border border-white/[0.07] bg-white/[0.02] px-4 py-1.5 text-sm font-medium text-slate-400"
413	          >
414	            {t}
415	          </span>
416	        ))}
417	      </div>
418	    </div>
419	  );
420	}
421	
422	/* ── Reasons bento ───────────────────────────────────────────────────────── */
423	function ReasonCard({ r, featured = false, delay }: { r: (typeof REASONS)[number]; featured?: boolean; delay: number }) {
424	  const { ref, seen } = useInViewOnce<HTMLDivElement>();
425	  return (
426	    <div
427	      ref={ref}
428	      className={`group relative flex flex-col overflow-hidden rounded-2xl border border-white/[0.07] bg-navy-900/60 backdrop-blur-md transition-all duration-700 ease-out hover:border-white/15 ${
429	        featured ? "h-full p-8" : "p-6"
430	      } ${seen ? "translate-y-0 opacity-100" : "translate-y-4 opacity-0"}`}
431	      style={{ transitionDelay: `${delay}ms` }}
432	    >
433	      {featured && (
434	        <div className="pointer-events-none absolute -right-10 -top-10 h-56 w-56 rounded-full bg-brand-500/12 opacity-70 blur-3xl" aria-hidden />
435	      )}
436	      <div className="flex items-center gap-3">
437	        <span className="flex items-center justify-center rounded-xl border border-white/10 bg-gradient-to-br from-brand-500/25 to-transparent text-brand-300" style={{ width: featured ? 52 : 44, height: featured ? 52 : 44 }}>
438	          <ReasonIcon icon={r.icon} size={featured ? 26 : 20} />
439	        </span>
440	        <span className="font-mono text-sm text-slate-600">{r.n}</span>
441	      </div>
442	      <h3 className={`mt-5 font-semibold text-white ${featured ? "text-2xl sm:text-3xl" : "text-lg"}`}>{r.title}</h3>
443	      <p className={`mt-2 leading-relaxed text-slate-400 ${featured ? "text-base max-w-md" : "text-sm"}`}>{r.body}</p>
444	      {featured && (
445	        <div className="mt-auto pt-8">
446	          <div className="inline-flex items-center gap-2.5 rounded-xl border border-white/10 bg-white/[0.03] px-4 py-2.5">
447	            <LiveDot />
448	            <span className="text-sm text-slate-300">
449	              Prompt to live: <span className="font-semibold text-accent-cyan">~47 seconds</span>
450	            </span>
451	          </div>
452	        </div>
453	      )}
454	    </div>
455	  );
456	}
457	
458	/* ── Main template ───────────────────────────────────────────────────────── */
459	/**
460	 * `heroBadges` / `reviewsBadges` are server-rendered <ReviewBadges/> nodes
461	 * injected by the (server) route — this is a client component, so the async
462	 * DB-backed badge component can't be imported here directly. Two independent
463	 * instances are passed so the real third-party review strip can appear in both
464	 * the hero and the reviews header (replacing the old hand-rolled star rows).
