52	export default async function VpsPage() {
53	  const [plans, templates, annualPct] = await Promise.all([
54	    db.plan.findMany({ where: { active: true }, orderBy: { sortOrder: "asc" } }),
55	    db.osTemplate.findMany({ where: { active: true }, orderBy: { sortOrder: "asc" } }),
56	    // Live admin annual discount, so the pricing cards can surface the real annual
57	    // $/mo and % saved (DB-fed, the same rate checkout charges).
58	    annualDiscountPct(),
59	  ]);
60	
61	  const OS_FAMILY_LABEL: Record<string, string> = {
62	    ubuntu: "Ubuntu", debian: "Debian", almalinux: "AlmaLinux", rocky: "Rocky Linux",
63	    fedora: "Fedora", centos: "CentOS", arch: "Arch Linux", alpine: "Alpine", opensuse: "openSUSE",
64	  };
65	  // Game-server families are shown on their own dedicated Game Server product
66	  // page, not here — without this filter every game (ARK, Satisfactory, V
67	  // Rising, ...) would double up inside the "One-click apps" showcase, since
68	  // they share the OsTemplate APPLICATION category with genuine apps like
69	  // Docker/WordPress. Sourced from lib/games.ts, the single canonical list.
70	  const gameFamilies = new Set<string>(GAME_FAMILIES);
71	  const byCat = (cat: string) => {
72	    const list = templates.filter((t) => t.category === cat && !(cat === "APPLICATION" && gameFamilies.has(t.family)));
73	    if (cat === "PLAIN_OS") {
74	      const seen = new Set<string>();
75	      const fams: string[] = [];
76	      for (const t of list) {
77	        const fam = (t.family || t.name).toLowerCase();
78	        if (seen.has(fam)) continue;
79	        seen.add(fam);
80	        fams.push(OS_FAMILY_LABEL[fam] ?? (t.family ? t.family[0].toUpperCase() + t.family.slice(1) : t.name));
81	      }
82	      return fams.length ? fams : FALLBACK[cat];
83	    }
84	    const live = list.map((t) => t.name);
85	    return live.length ? live : FALLBACK[cat];
86	  };
87	  const groups: CatalogGroup[] = (["PLAIN_OS", "CONTROL_PANEL", "APPLICATION"] as const).map((cat) => ({
88	    key: cat,
89	    label: CATEGORY_LABELS[cat],
90	    items: byCat(cat),
91	  }));
92	  const totalImages = groups.reduce((n, g) => n + g.items.length, 0);
93	
94	  // Real plans, mapped to the template's ConfigStop shape so the interactive
95	  // configurator drives off live DB pricing/specs instead of illustrative
96	  // preview numbers. Same "middle plan is Popular" heuristic as PricingGrid.
97	  const popularIdx = plans.length ? Math.floor((plans.length - 1) / 2) : -1;
98	  const configStops: ConfigStop[] = plans.map((p, i) => ({
99	    id: p.slug,
100	    tier: p.name,
101	    ram: Math.round(p.ramMB / 1024),
102	    vcpu: p.cpuCores,
103	    nvme: p.diskGB,
104	    bandwidth: p.bandwidthTB,
105	    price: money(p.priceCents),
106	    popular: i === popularIdx,
107	    blurb: planTip(p),
108	  }));
109	
110	  return (
111	    <>
112	      <FaqJsonLd items={FAQ} />
113	      {plans.length > 0 && <ProductJsonLd plans={plans} />}
114	      <VpsLanding reviewBadges={<ReviewBadges />} configStops={configStops} />
115	
116	      {/* Deploy catalog — real one-click OS/control-panel/app images from the
117	          DB. The template's "everything included" grid names a couple of
118	          examples but doesn't browse the full catalog, so it's kept as its
119	          own section in the established brand system (Section/SectionTitle),
120	          right where visitors expect it after the configurator. */}
121	      <Section tone="panel" size="lg">
122	        <SectionTitle
123	          eyebrow="Deploy anything"
124	          title="Your stack, ready on first boot"
125	          sub={`Pick from ${totalImages}+ images across operating systems, control panels, and one-click apps — then customise everything with full root access.`}
126	        />
127	        <Reveal className="mt-12">
128	          <DeployCatalog groups={groups} />
129	        </Reveal>
130	        <p className="mt-8 text-center text-sm text-slate-400">
131	          Running WordPress? See our guide to the{" "}
132	          <Link href="/blog/best-vps-for-wordpress" className="font-medium text-brand-300 hover:text-brand-200">
133	            best VPS for WordPress
134	          </Link>
135	          .
136	        </p>
137	      </Section>
138	
139	      {/* FAQ */}
140	      <Section size="md">
141	        <SectionTitle eyebrow="FAQ" title="Questions, answered" />
142	        <div className="mx-auto mt-10 max-w-3xl space-y-4">
143	          {FAQ.map((f) => (
144	            <div key={f.q} className="card">
