126	  const preview = useMemo(() => {
127	    const parts: React.ReactNode[] = [];
128	    const re = /\{([A-Z0-9_]+)\}/g;
129	    let last = 0;
130	    let m: RegExpExecArray | null;
131	    let idx = 0;
132	    while ((m = re.exec(tmpl.prompt))) {
133	      if (m.index > last) parts.push(tmpl.prompt.slice(last, m.index));
134	      const v = values[m[1]]?.trim();
