3	/**
4	 * Co-located client kit for the AI / vibe-coding hosting PREVIEW template
5	 * (components/marketing/aihostingtemplate/*). Small, self-contained hooks +
6	 * atoms so the template is isolated and independently shippable — it imports
7	 * nothing mutable from the rest of the tree. Everything respects
8	 * prefers-reduced-motion: motion hooks resolve to their final resting value.
9	 *
10	 * Net-new, preview-only. Touches no live page or shared component.
11	 */
12	
13	import { useEffect, useRef, useState } from "react";
14	
15	export function usePrefersReducedMotion() {
16	  const [reduced, setReduced] = useState(false);
17	  useEffect(() => {
18	    const mq = window.matchMedia?.("(prefers-reduced-motion: reduce)");
19	    if (!mq) return;
20	    setReduced(mq.matches);
21	    const on = () => setReduced(mq.matches);
22	    mq.addEventListener?.("change", on);
23	    return () => mq.removeEventListener?.("change", on);
24	  }, []);
25	  return reduced;
26	}
27	
28	/** Fires once when the element first scrolls into view. */
29	export function useInViewOnce<T extends HTMLElement = HTMLDivElement>(margin = "0px 0px -12% 0px") {
30	  const ref = useRef<T | null>(null);
31	  const [seen, setSeen] = useState(false);
32	  useEffect(() => {
33	    const el = ref.current;
34	    if (!el || typeof IntersectionObserver === "undefined") {
35	      setSeen(true);
36	      return;
37	    }
38	    const io = new IntersectionObserver(
39	      ([e]) => {
40	        if (e.isIntersecting) {
41	          setSeen(true);
42	          io.disconnect();
43	        }
44	      },
45	      { threshold: 0.2, rootMargin: margin },
46	    );
47	    io.observe(el);
48	    return () => io.disconnect();
49	  }, [margin]);
50	  return { ref, seen };
51	}
52	
53	/** Smoothly counts up to `target` once `active`. Immediate under reduced motion. */
54	export function useCountUp(target: number, active: boolean, duration = 1100, reduced = false) {
55	  const [val, setVal] = useState(reduced ? target : 0);
56	  useEffect(() => {
57	    if (!active) return;
58	    if (reduced) {
59	      setVal(target);
60	      return;
61	    }
62	    let raf = 0;
63	    const start = performance.now();
64	    const tick = (now: number) => {
65	      const t = Math.min(1, (now - start) / duration);
66	      const eased = 1 - Math.pow(1 - t, 3);
67	      setVal(Math.round(target * eased));
68	      if (t < 1) raf = requestAnimationFrame(tick);
69	    };
70	    raf = requestAnimationFrame(tick);
71	    return () => cancelAnimationFrame(raf);
72	  }, [target, active, duration, reduced]);
73	  return val;
74	}
