67	function BootConsole() {
68	  const reduced = usePrefersReducedMotion();
69	  const cmd = BOOT_LINES[0];
70	  const steps = BOOT_LINES.slice(1);
71	
72	  const [typed, setTyped] = useState(reduced ? cmd : "");
73	  const [shown, setShown] = useState(reduced ? steps.length : 0);
74	  const [phase, setPhase] = useState<"type" | "run" | "live">(reduced ? "live" : "type");
75	  const timers = useRef<ReturnType<typeof setTimeout>[]>([]);
76	
77	  const live = phase === "live";
78	  const cpu = useJitter(34, 5, live, 2200, reduced);
79	  const ram = useJitter(58, 4, live, 2600, reduced);
80	  const net = useJitter(128, 14, live, 2000, reduced);
81	
82	  useEffect(() => {
83	    if (reduced) return;
84	    let dead = false;
85	    const push = (fn: () => void, ms: number) => {
86	      if (!dead) timers.current.push(setTimeout(fn, ms));
87	    };
88	    const run = () => {
89	      setTyped("");
90	      setShown(0);
91	      setPhase("type");
92	      cmd.split("").forEach((_, i) => push(() => setTyped(cmd.slice(0, i + 1)), 42 * i + 350));
93	      const afterType = 42 * cmd.length + 650;
94	      push(() => setPhase("run"), afterType);
95	      steps.forEach((_, i) => push(() => setShown(i + 1), afterType + 480 * (i + 1)));
96	      const afterSteps = afterType + 480 * (steps.length + 1);
97	      push(() => setPhase("live"), afterSteps);
98	      push(run, afterSteps + 4200); // loop
99	    };
100	    run();
101	    return () => {
102	      dead = true;
103	      timers.current.forEach(clearTimeout);
104	      timers.current = [];
105	    };
106	    // eslint-disable-next-line react-hooks/exhaustive-deps
107	  }, [reduced]);
108	
109	  const progress = live ? 100 : (shown / steps.length) * 100;
110	
111	  return (
112	    <div className={reduced ? "" : "pv-float"}>
113	      <div className="glass relative overflow-hidden rounded-2xl border-white/10 shadow-2xl glow-brand">
114	        {/* brand aura */}
