/**
 * Smart, spec-derived guidance for a plan. Given a plan's resources, returns a
 * short "great for…" line so visitors can self-select the right box at a glance.
 * Pure function — safe on the server and the client.
 */

export type PlanLike = {
  cpuCores: number;
  ramMB: number;
  diskGB: number;
};

/** One-line "great for…" recommendation derived from a plan's RAM (and cores). */
export function planTip(plan: PlanLike): string {
  const ram = plan.ramMB;
  if (ram <= 2048) return "Personal sites, dev/staging, bots, VPNs";
  if (ram <= 4096) return "WordPress & WooCommerce, small game servers, CI runners";
  if (ram <= 8192) return "Busy sites, databases, Docker stacks, small multiplayer servers";
  return "High-traffic apps, big databases, multiple sites, heavy workloads";
}

/** A tighter one/two-word audience label, handy for badges. */
export function planAudience(plan: PlanLike): string {
  const ram = plan.ramMB;
  if (ram <= 2048) return "Starter";
  if (ram <= 4096) return "Growth";
  if (ram <= 8192) return "Scale";
  return "Power";
}
