"use client";

/**
 * LIVE component for /vibe-coding ("Build with Claude Code, on your own VPS").
 *
 * Ports the visual language from the AI-hosting PREVIEW direction (aurora hero,
 * animated console, stack ribbon, bento reasons — see AIHostingTemplate.tsx)
 * onto the REAL product. Nxeon does not sell a separate "AI hosting" plan, a
 * multi-platform import wizard, or a review-before-deploy approval flow — those
 * were the preview's illustrative, not-yet-built ideas. What's real: Claude Code
 * (the actual Anthropic CLI) ships pre-installed on every Nxeon VPS, customers
 * bring their own Claude subscription or Anthropic API key, and there's no
 * pricing here beyond the VPS itself (see /vps). Every claim below is checked
 * against lib/claude-install.ts, lib/ai-build.ts, and components/customer/
 * claude-code/ClaudeCodeHub.tsx — the actual install + setup mechanism.
 */

import Link from "next/link";
import { useEffect, useRef, useState, type ReactNode } from "react";
import styles from "./aihosting.module.css";
import { usePrefersReducedMotion, useInViewOnce, LiveDot } from "./kit";
import { ClaudeMark } from "@/components/marketing/ClaudeMark";
import { IconCheck, IconArrow, IconBolt, IconServer, IconTerminal, IconClock, IconScale } from "@/components/marketing/icons";

/* ── Hero centerpiece: a real first session, typed out ───────────────────── */
type ConsoleLine = { kind: "you" | "claude" | "ok" | "dim"; text: string };

const PROMPT_TEXT = "Build a booking site for my salon — services, a gallery, and a contact form.";

const BUILD_LINES: ConsoleLine[] = [
  { kind: "claude", text: "On it — scaffolding a Next.js + Tailwind site…" },
  { kind: "ok", text: "✓ Home page with hero + booking button" },
  { kind: "ok", text: "✓ Services list and photo gallery" },
  { kind: "ok", text: "✓ Contact form wired up" },
  { kind: "claude", text: "Starting it up so you can preview…" },
];

function SetupConsole() {
  const reduced = usePrefersReducedMotion();
  const { ref, seen } = useInViewOnce<HTMLDivElement>();
  const [typed, setTyped] = useState("");
  const [phase, setPhase] = useState<"idle" | "typing" | "building" | "done">("idle");
  const [built, setBuilt] = useState(0);
  const timers = useRef<ReturnType<typeof setTimeout>[]>([]);

  useEffect(() => {
    if (!seen) return;
    if (reduced) {
      setTyped(PROMPT_TEXT);
      setBuilt(BUILD_LINES.length);
      setPhase("done");
      return;
    }
    let dead = false;
    const push = (fn: () => void, ms: number) => {
      if (!dead) timers.current.push(setTimeout(fn, ms));
    };
    const run = () => {
      setTyped("");
      setBuilt(0);
      setPhase("typing");
      const charMs = 32;
      PROMPT_TEXT.split("").forEach((_, i) => push(() => setTyped(PROMPT_TEXT.slice(0, i + 1)), 300 + charMs * i));
      const afterType = 300 + charMs * PROMPT_TEXT.length + 500;
      push(() => setPhase("building"), afterType);
      BUILD_LINES.forEach((_, i) => push(() => setBuilt(i + 1), afterType + 650 * (i + 1)));
      const afterBuild = afterType + 650 * (BUILD_LINES.length + 1);
      push(() => setPhase("done"), afterBuild);
      push(run, afterBuild + 5000); // loop
    };
    run();
    return () => {
      dead = true;
      timers.current.forEach(clearTimeout);
      timers.current = [];
    };
  }, [seen, reduced]);

  const showBuild = phase === "building" || phase === "done";
  const showSite = phase === "done";

  return (
    <div ref={ref} className={reduced ? "" : "pv-float-slow"}>
      <div className="relative grid gap-4 sm:grid-cols-[1.05fr_0.95fr] sm:items-start">
        <div
          className="pointer-events-none absolute -inset-28 -z-10"
          style={{
            background:
              "radial-gradient(50% 50% at 22% 14%, rgba(59,130,246,0.26), rgba(59,130,246,0) 66%), radial-gradient(52% 52% at 88% 92%, rgba(138,112,251,0.28), rgba(138,112,251,0) 66%)",
            filter: "blur(44px)",
          }}
          aria-hidden
        />

        {/* Claude session panel */}
        <div className="relative overflow-hidden rounded-2xl border border-white/10 bg-[#080d18]/90 shadow-2xl shadow-black/50 backdrop-blur-xl">
          <div className="flex items-center gap-2 border-b border-white/[0.06] bg-white/[0.02] px-4 py-2.5">
            <span className="flex h-6 w-6 items-center justify-center rounded-md bg-gradient-to-br from-accent-blue to-brand-500 text-white">
              <ClaudeMark size={13} />
            </span>
            <span className="text-[12px] font-medium text-slate-300">claude · your Nxeon VPS</span>
            <span className="ml-auto inline-flex items-center gap-1.5 rounded-full bg-emerald-500/12 px-2 py-0.5 text-[10px] font-medium text-emerald-300">
              <span className="h-1.5 w-1.5 rounded-full bg-emerald-400 motion-safe:animate-pulse-dot" />
              pre-installed
            </span>
          </div>

          <div className="space-y-3 px-4 py-4 text-[13px] leading-relaxed">
            <div className="text-slate-500">
              <span className="select-none text-slate-600">$ </span>ssh root@your-server-ip
            </div>
            <div className="text-slate-500">
              <span className="select-none text-slate-600">$ </span>claude
            </div>
            <div className="text-[#e8a889]">
              <span className="select-none text-[#D97757]">✳ </span>What would you like to build?
            </div>

            <div className="relative ml-auto max-w-[92%] rounded-2xl rounded-br-sm border border-brand-500/25 bg-brand-500/10 px-3.5 py-2.5 text-slate-100">
              <span className="invisible" aria-hidden>
                {PROMPT_TEXT}
              </span>
              <span className="absolute inset-0 px-3.5 py-2.5">
                {typed || <span className="text-slate-500">Describe what you want to build…</span>}
                {phase === "typing" && (
                  <span className="ml-0.5 inline-block h-3.5 w-1.5 translate-y-[2px] bg-brand-300 motion-safe:animate-blink" />
                )}
              </span>
            </div>

            <div
              className={`max-w-[94%] rounded-2xl rounded-bl-sm border border-white/[0.07] bg-white/[0.03] px-3.5 py-3 motion-safe:transition-opacity motion-safe:duration-500 ${
                showBuild ? "opacity-100" : "opacity-0"
              }`}
              aria-hidden={!showBuild}
            >
              <ul className="space-y-1.5 font-mono text-[12px]">
                {BUILD_LINES.map((l, i) => {
                  const shown = built > i;
                  return (
                    <li
                      key={i}
                      className={`motion-safe:transition-opacity motion-safe:duration-300 ${shown ? "opacity-100" : "opacity-0"} ${
                        l.kind === "ok" ? "font-semibold text-emerald-300" : "text-slate-300"
                      }`}
                    >
                      {l.text}
                    </li>
                  );
                })}
              </ul>
            </div>
          </div>

          <div className="border-t border-white/[0.06] px-4 py-3">
            <div className="flex items-center gap-2 rounded-xl border border-white/10 bg-white/[0.03] px-3 py-2 text-[12px] text-slate-500">
              Ask Claude to build or change anything
              <span className="inline-block h-3.5 w-1.5 bg-slate-500 motion-safe:animate-blink" />
              <span className="ml-auto flex h-6 w-6 items-center justify-center rounded-lg bg-gradient-to-br from-accent-blue to-brand-500 text-white">
                <ClaudeMark size={12} />
              </span>
            </div>
          </div>
        </div>

        {/* result: your app, running on your own server */}
        <div className="relative">
          <div className="overflow-hidden rounded-2xl border border-white/10 bg-white shadow-2xl shadow-black/40">
            <div className="flex items-center gap-2 border-b border-black/10 bg-slate-100 px-3 py-2">
              <span className="h-2.5 w-2.5 rounded-full bg-[#ff5f57]" />
              <span className="h-2.5 w-2.5 rounded-full bg-[#febc2e]" />
              <span className="h-2.5 w-2.5 rounded-full bg-[#28c840]" />
              <span className="ml-2 flex-1 truncate rounded-md bg-white px-2.5 py-1 text-[10px] text-slate-500 ring-1 ring-black/5">
                {showSite ? "your-domain.com" : "starting preview…"}
              </span>
            </div>
            <div className="relative min-h-[248px] bg-gradient-to-b from-[#faf7f2] to-white">
              {!showSite ? (
                <div className="flex min-h-[248px] flex-col items-center justify-center gap-3 px-6 text-center">
                  <span className="flex h-9 w-9 items-center justify-center rounded-full border-2 border-brand-500/30 border-t-brand-500 motion-safe:animate-orbit-spin" />
                  <p className="text-[12px] font-medium text-slate-400">Claude is building your site…</p>
                </div>
              ) : (
                <div className="px-4 py-3">
                  <div className={`flex items-center justify-between ${reduced ? "" : styles.rise}`} style={{ animationDelay: "0ms" }}>
                    <span className="text-[13px] font-bold tracking-tight text-emerald-800">Lumen Salon</span>
                    <div className="hidden gap-2 text-[9px] text-slate-500 sm:flex">
                      <span>Services</span>
                      <span>Gallery</span>
                      <span className="rounded-full bg-emerald-700 px-2 py-0.5 text-white">Book</span>
                    </div>
                  </div>
                  <div className={`mt-3 text-center ${reduced ? "" : styles.rise}`} style={{ animationDelay: "90ms" }}>
                    <p className="text-[9px] font-semibold uppercase tracking-[0.2em] text-emerald-700">Wellness &amp; calm</p>
                    <h4 className="mt-1 text-base font-bold leading-tight text-slate-800">
                      Relax, restore, <span className="text-emerald-700">renew.</span>
                    </h4>
                    <span className="mt-2 inline-block rounded-full bg-emerald-700 px-3 py-1 text-[10px] font-semibold text-white">
                      Book an appointment
                    </span>
                  </div>
                  <div className="mt-3 grid grid-cols-3 gap-2">
                    {["Massage", "Facials", "Sauna"].map((s, i) => (
                      <div
                        key={s}
                        className={`rounded-lg bg-white p-2 text-left shadow-sm ring-1 ring-black/5 ${reduced ? "" : styles.rise}`}
                        style={{ animationDelay: `${180 + i * 90}ms` }}
                      >
                        <div className="mb-1.5 h-6 rounded bg-emerald-100" />
                        <p className="text-[9px] font-semibold text-slate-700">{s}</p>
                        <p className="text-[8px] text-slate-400">from $60</p>
                      </div>
                    ))}
                  </div>
                </div>
              )}
            </div>
          </div>
          <div className="mt-3 inline-flex items-center gap-2 rounded-full border border-white/10 bg-white/[0.04] px-3 py-1.5 text-[12px] text-slate-300 backdrop-blur-md">
            <LiveDot />
            {showSite ? (
              <>
                Running on your server · point <span className="font-semibold text-accent-cyan">your own domain</span> at it whenever you're ready
              </>
            ) : (
              <>Building on your server…</>
            )}
          </div>
        </div>
      </div>
    </div>
  );
}

/* ── Stack ribbon ─────────────────────────────────────────────────────────── */
const STACK = ["Next.js", "React", "Vite", "Node", "Postgres", "Python", "Astro", "Express", "Prisma", "Tailwind", "SvelteKit", "Remix"];
function StackRibbon() {
  return (
    <div className={`${styles.marquee} relative overflow-hidden`}>
      <div className="pointer-events-none absolute inset-y-0 left-0 z-10 w-24 bg-gradient-to-r from-navy-950 to-transparent" aria-hidden />
      <div className="pointer-events-none absolute inset-y-0 right-0 z-10 w-24 bg-gradient-to-l from-navy-950 to-transparent" aria-hidden />
      <div className={styles.marqueeTrack} aria-hidden>
        {[...STACK, ...STACK].map((t, i) => (
          <span key={i} className="mx-1.5 shrink-0 rounded-full border border-white/[0.07] bg-white/[0.02] px-4 py-1.5 text-sm font-medium text-slate-400">
            {t}
          </span>
        ))}
      </div>
    </div>
  );
}

/* ── "Bring your own Claude" — the two REAL sign-in paths ─────────────────── */
type SetupPath = { id: string; label: string; tagline: string; best: string; lines: ConsoleLine[] };

const SETUP_PATHS: SetupPath[] = [
  {
    id: "subscription",
    label: "Your Claude subscription",
    tagline: "Log in with the Claude Pro or Max account you already pay for.",
    best: "No extra cost per project — your existing usage allowance applies.",
    lines: [
      { kind: "dim", text: "How would you like to log in?" },
      { kind: "dim", text: "  1. Subscription (Claude Pro or Max)" },
      { kind: "dim", text: "  2. Anthropic API key" },
      { kind: "you", text: "1" },
      { kind: "dim", text: "Opening browser to authorize…" },
      { kind: "ok", text: "✓ Logged in as you@example.com" },
    ],
  },
  {
    id: "apikey",
    label: "An Anthropic API key",
    tagline: "Create a key at console.anthropic.com and export it once.",
    best: "Pay-as-you-go — billed by Anthropic directly, separate from your Nxeon bill.",
    lines: [
      { kind: "dim", text: "# from the Anthropic Console" },
      { kind: "you", text: "export ANTHROPIC_API_KEY=sk-ant-…" },
      { kind: "dim", text: "# keep it for next time you log in" },
      { kind: "you", text: "echo 'export ANTHROPIC_API_KEY=sk-ant-…' >> ~/.bashrc" },
      { kind: "ok", text: "✓ API key saved" },
    ],
  },
];

function SetupTerminal({ lines }: { lines: ConsoleLine[] }) {
  return (
    <div className="overflow-hidden rounded-2xl border border-white/10 bg-black/60 shadow-2xl backdrop-blur-sm">
      <div className="flex items-center gap-1.5 border-b border-white/[0.06] px-4 py-2.5">
        <span className="h-2.5 w-2.5 rounded-full bg-red-500/70" />
        <span className="h-2.5 w-2.5 rounded-full bg-amber-400/70" />
        <span className="h-2.5 w-2.5 rounded-full bg-emerald-400/70" />
        <span className="ml-2 font-mono text-[11px] uppercase tracking-widest text-slate-500">claude · first run</span>
      </div>
      <div className="min-h-[168px] space-y-1.5 p-4 font-mono text-[12.5px] leading-relaxed">
        {lines.map((l, i) => (
          <div
            key={i}
            className={
              l.kind === "ok"
                ? "font-semibold text-emerald-300"
                : l.kind === "you"
                  ? "text-amber-200"
                  : "text-slate-400"
            }
          >
            {l.kind === "you" && <span className="select-none text-slate-600">{"> "}</span>}
            {l.text}
          </div>
        ))}
      </div>
    </div>
  );
}

function SetupShowcase() {
  const [active, setActive] = useState(0);
  const path = SETUP_PATHS[active];
  return (
    <div className="grid gap-8 lg:grid-cols-2 lg:items-center lg:gap-12">
      <div>
        <span className="eyebrow">No new subscription to buy</span>
        <h2 className="mt-3 text-3xl font-bold tracking-tight text-white sm:text-4xl">
          Sign in with the <span className="grad-text">Claude account you already have</span>
        </h2>
        <p className="mt-4 max-w-md text-lg leading-relaxed text-slate-400">
          The first time you run <code className="rounded bg-white/10 px-1.5 py-0.5 text-slate-200">claude</code> on your
          server, it asks how to log in. Pick a subscription or an API key — Nxeon doesn't charge for either.
        </p>
        <div className="mt-6 flex flex-wrap gap-2.5">
          {SETUP_PATHS.map((p, i) => (
            <button
              key={p.id}
              type="button"
              onClick={() => setActive(i)}
              aria-pressed={i === active}
              className={`inline-flex items-center gap-2 rounded-xl border px-3.5 py-2 text-sm font-medium transition-all ${
                i === active
                  ? "border-transparent bg-white/[0.06] text-white shadow-[0_0_0_1px_rgba(111,71,245,0.4),0_12px_30px_-16px_rgba(111,71,245,0.6)]"
                  : "border-white/10 bg-white/[0.02] text-slate-400 hover:border-white/20 hover:text-slate-200"
              }`}
            >
              {p.label}
            </button>
          ))}
        </div>
        <p className="mt-4 max-w-md text-sm leading-relaxed text-slate-500">
          <span className="font-semibold text-slate-300">{path.tagline}</span> {path.best}
        </p>
        <Link href="/dashboard/claude-code" className="btn-primary mt-7 inline-flex px-6 py-3 text-base">
          See the full setup guide
          <IconArrow size={16} />
        </Link>
      </div>
      <SetupTerminal lines={path.lines} />
    </div>
  );
}

/* ── Reasons bento ────────────────────────────────────────────────────────── */
type Reason = { n: string; title: string; body: string; icon: ReactNode };

const REASONS: Reason[] = [
  {
    n: "01",
    title: "Claude Code ships on every VPS",
    body: "New servers get it automatically at first boot — nothing to install before you start. On an older server, one command adds it.",
    icon: <IconTerminal size={26} />,
  },
  {
    n: "02",
    title: "No separate product or price",
    body: "This isn't a pricier \"AI hosting\" tier — it's the same VPS you'd deploy anyway. See real pricing below or on the full VPS page.",
    icon: <IconScale size={20} />,
  },
  {
    n: "03",
    title: "A real server, not a sandbox",
    body: "Full root, your own database, resizable RAM/vCPU/NVMe. Whatever Claude builds keeps running after you close the tab.",
    icon: <IconServer size={20} />,
  },
  {
    n: "04",
    title: "Runs after your laptop sleeps",
    body: "Long builds, cron jobs, and always-on services keep going on the server — they don't stop when you shut the lid.",
    icon: <IconClock size={20} />,
  },
];

function ReasonCard({ r, featured = false, delay }: { r: Reason; featured?: boolean; delay: number }) {
  const { ref, seen } = useInViewOnce<HTMLDivElement>();
  return (
    <div
      ref={ref}
      className={`group relative flex flex-col overflow-hidden rounded-2xl border border-white/[0.07] bg-navy-900/60 backdrop-blur-md transition-all duration-700 ease-out hover:border-white/15 ${
        featured ? "h-full p-8" : "p-6"
      } ${seen ? "translate-y-0 opacity-100" : "translate-y-4 opacity-0"}`}
      style={{ transitionDelay: `${delay}ms` }}
    >
      {featured && <div className="pointer-events-none absolute -right-10 -top-10 h-56 w-56 rounded-full bg-brand-500/12 opacity-70 blur-3xl" aria-hidden />}
      <div className="flex items-center gap-3">
        <span
          className="flex items-center justify-center rounded-xl border border-white/10 bg-gradient-to-br from-brand-500/25 to-transparent text-brand-300"
          style={{ width: featured ? 52 : 44, height: featured ? 52 : 44 }}
        >
          {r.icon}
        </span>
        <span className="font-mono text-sm text-slate-600">{r.n}</span>
      </div>
      <h3 className={`mt-5 font-semibold text-white ${featured ? "text-2xl sm:text-3xl" : "text-lg"}`}>{r.title}</h3>
      <p className={`mt-2 leading-relaxed text-slate-400 ${featured ? "max-w-md text-base" : "text-sm"}`}>{r.body}</p>
    </div>
  );
}

/* ── VPS vs. your laptop — a genuine, defensible comparison ───────────────── */
const COMPARE_ROWS: { point: string; laptop: string; vps: string }[] = [
  { point: "When you close the lid", laptop: "The session ends — Claude stops mid-task.", vps: "Nothing changes. The server keeps running." },
  { point: "A long build or refactor", laptop: "Sleep, reboots, or a dropped Wi-Fi connection can interrupt it.", vps: "Keeps going in your SSH session (or a detached tmux) whether you're watching or not." },
  { point: "Reaching it", laptop: "Tied to whichever machine you started on.", vps: "SSH in from your phone, a tablet, or a different computer — same session." },
  { point: "What Claude builds", laptop: "A dev server that dies the moment you shut down.", vps: "An app, bot, or API that stays reachable, because the box never sleeps." },
];

function CompareTable() {
  return (
    <div className="overflow-hidden rounded-2xl border border-white/[0.08]">
      <div className="grid grid-cols-[1.1fr_1fr_1fr] bg-white/[0.03] text-xs font-semibold uppercase tracking-wider text-slate-400">
        <div className="px-4 py-3 sm:px-5">&nbsp;</div>
        <div className="px-4 py-3 sm:px-5">Your laptop</div>
        <div className="px-4 py-3 text-brand-200 sm:px-5">Nxeon VPS</div>
      </div>
      {COMPARE_ROWS.map((row, i) => (
        <div
          key={row.point}
          className={`grid grid-cols-[1.1fr_1fr_1fr] border-t border-white/[0.06] text-sm ${i % 2 === 1 ? "bg-white/[0.015]" : ""}`}
        >
          <div className="px-4 py-4 font-semibold text-white sm:px-5">{row.point}</div>
          <div className="px-4 py-4 text-slate-500 sm:px-5">{row.laptop}</div>
          <div className="flex items-start gap-2 px-4 py-4 text-slate-200 sm:px-5">
            <span className="mt-0.5 flex h-4 w-4 flex-none items-center justify-center rounded-full bg-emerald-500/15 text-emerald-400">
              <IconCheck size={10} />
            </span>
            {row.vps}
          </div>
        </div>
      ))}
    </div>
  );
}

/* ── Real pricing teaser (fed by live DB plans, same as /vps) ─────────────── */
export type PricePlan = {
  id: string;
  tier: string;
  price: string;
  ram: number;
  vcpu: number;
  nvme: number;
  blurb: string;
  popular?: boolean;
};

function PricingTeaser({ plans }: { plans: PricePlan[] }) {
  if (plans.length === 0) return null;
  return (
    <div>
      <div className="mx-auto max-w-2xl text-center">
        <span className="eyebrow">Real VPS pricing</span>
        <h2 className="mt-3 text-3xl font-bold tracking-tight text-white sm:text-4xl">One price. No AI-hosting markup.</h2>
        <p className="mt-4 text-lg text-slate-400">
          Claude Code is included on every plan at no extra cost — this is the same pricing as the full{" "}
          <Link href="/vps" className="font-medium text-brand-300 hover:text-brand-200">
            VPS configurator
          </Link>
          .
        </p>
      </div>
      <div className="mx-auto mt-12 grid max-w-5xl gap-5 md:grid-cols-3">
        {plans.map((p) => (
          <div
            key={p.id}
            className={`relative flex flex-col rounded-2xl border p-6 backdrop-blur-md transition-all duration-200 ${
              p.popular
                ? "border-brand-500/40 bg-navy-900/80 shadow-2xl shadow-black/40 glow-brand"
                : "border-white/[0.07] bg-navy-900/50 hover:border-white/15"
            }`}
          >
            {p.popular && (
              <span className="absolute -top-3 left-1/2 -translate-x-1/2 rounded-full border border-brand-500/30 bg-brand-500/15 px-3 py-1 text-[11px] font-semibold uppercase tracking-[0.12em] text-brand-200">
                Most popular
              </span>
            )}
            <p className="text-xs font-semibold uppercase tracking-wider text-brand-300">{p.tier}</p>
            <p className="mt-2">
              <span className="text-4xl font-bold text-white">{p.price}</span>
              <span className="text-sm text-slate-500">/mo</span>
            </p>
            <p className="mt-2 text-sm leading-relaxed text-slate-400">{p.blurb}</p>
            <ul className="mt-5 flex-1 space-y-2.5 border-t border-white/[0.06] pt-5 text-sm text-slate-300">
              <li className="flex items-center gap-2.5">
                <span className="flex h-[18px] w-[18px] flex-none items-center justify-center rounded-full bg-emerald-500/15 text-emerald-400">
                  <IconCheck size={12} />
                </span>
                {p.ram} GB RAM · {p.vcpu} vCPU · {p.nvme} GB NVMe
              </li>
              <li className="flex items-center gap-2.5">
                <span className="flex h-[18px] w-[18px] flex-none items-center justify-center rounded-full bg-emerald-500/15 text-emerald-400">
                  <IconCheck size={12} />
                </span>
                Claude Code pre-installed
              </li>
              <li className="flex items-center gap-2.5">
                <span className="flex h-[18px] w-[18px] flex-none items-center justify-center rounded-full bg-emerald-500/15 text-emerald-400">
                  <IconCheck size={12} />
                </span>
                Full root · your own domain
              </li>
            </ul>
            <Link href="/vps" className={`mt-6 block rounded-xl px-4 py-2.5 text-center text-sm font-semibold ${p.popular ? "btn-deploy" : "btn-secondary"}`}>
              Deploy &amp; start building
            </Link>
          </div>
        ))}
      </div>
    </div>
  );
}

/* ── Main landing ─────────────────────────────────────────────────────────── */
export function VibeCodingLanding({
  heroBadges,
  plans,
}: {
  heroBadges?: ReactNode;
  plans: PricePlan[];
}) {
  return (
    <div className="relative">
      {/* HERO */}
      <section className="relative isolate overflow-hidden">
        <div className="pointer-events-none absolute inset-0 -z-10 overflow-hidden" aria-hidden>
          <div
            className={`absolute inset-x-0 -top-1/3 h-[90vh] ${styles.aurora}`}
            style={{
              background:
                "radial-gradient(45% 45% at 20% 20%, rgba(111,71,245,0.20), transparent 70%), radial-gradient(40% 45% at 80% 10%, rgba(34,211,238,0.14), transparent 70%), radial-gradient(45% 40% at 60% 60%, rgba(59,130,246,0.14), transparent 70%)",
            }}
          />
        </div>

        <div className="rail grid items-center gap-12 py-20 lg:grid-cols-12 lg:gap-8 lg:py-24">
          <div className="lg:col-span-5">
            <span className="inline-flex items-center gap-2 rounded-full border border-brand-500/30 bg-brand-500/10 px-3 py-1.5 text-xs font-semibold text-brand-200">
              <ClaudeMark size={14} />
              Claude Code · pre-installed on every VPS
            </span>
            <h1 className="mt-5 text-[2.6rem] font-bold leading-[1.04] tracking-tight text-white sm:text-6xl">
              Describe your idea. <span className="grad-text">Claude builds it — on your own server.</span>
            </h1>
            <p className="mt-6 max-w-xl text-lg leading-relaxed text-slate-300/90">
              Say what you want in plain English and Claude Code — the real Anthropic CLI, already installed on every
              Nxeon VPS — writes the code, runs it, and gets it live. Bring the Claude subscription you already pay for,
              or an Anthropic API key. No separate plan to buy.
            </p>

            <div className="mt-8 inline-flex items-center gap-3 rounded-2xl border border-white/10 bg-white/[0.04] px-4 py-3 backdrop-blur-md">
              <LiveDot />
              <span className="text-base font-medium text-slate-200 sm:text-lg">
                Nothing to set up first — <span className="font-bold text-accent-cyan">it's already there.</span>
              </span>
            </div>

            <div className="mt-8 flex flex-wrap items-center gap-3">
              <Link href="/vps" className="btn-deploy px-6 py-3 text-base">
                See VPS plans
                <span className="dep-arrow" aria-hidden>→</span>
              </Link>
              <Link href="#how" className="btn-secondary px-5 py-3 text-base">
                See how it works
              </Link>
            </div>

            {heroBadges && <div className="mt-7">{heroBadges}</div>}
          </div>

          <div className="lg:col-span-7 lg:pl-6">
            <SetupConsole />
          </div>
        </div>

        <div className="relative border-y border-white/[0.06] bg-navy-950/50 py-4 backdrop-blur-sm">
          <div className="rail flex items-center gap-4">
            <span className="hidden shrink-0 text-xs font-semibold uppercase tracking-wider text-slate-500 sm:block">Build anything</span>
            <StackRibbon />
          </div>
        </div>
      </section>

      {/* SETUP — the two real sign-in paths */}
      <section id="setup" className="rail scroll-mt-24 py-24">
        <SetupShowcase />
      </section>

      {/* REASONS */}
      <section id="how" className="tone-panel scroll-mt-24 py-24">
        <div className="rail">
          <div className="max-w-2xl">
            <span className="eyebrow">Why build here</span>
            <h2 className="mt-3 text-3xl font-bold tracking-tight text-white sm:text-4xl">
              Real hosting underneath, not a demo sandbox
            </h2>
          </div>
          <div className="mt-12 grid gap-4 lg:grid-cols-2">
            <ReasonCard r={REASONS[0]} featured delay={0} />
            <div className="flex flex-col gap-4">
              {REASONS.slice(1).map((r, i) => (
                <ReasonCard key={r.n} r={r} delay={(i + 1) * 70} />
              ))}
            </div>
          </div>
        </div>
      </section>

      {/* VPS vs. laptop */}
      <section className="rail py-24">
        <div className="mx-auto max-w-2xl text-center">
          <span className="eyebrow">Persistent vs. local</span>
          <h2 className="mt-3 text-3xl font-bold tracking-tight text-white sm:text-4xl">
            A dedicated box beats a laptop for long-running builds
          </h2>
          <p className="mt-4 text-lg text-slate-400">
            You can run Claude Code on your own machine too — it's the same CLI. Here's what changes when it runs on a
            server that never sleeps instead.
          </p>
        </div>
        <div className="mx-auto mt-12 max-w-4xl">
          <CompareTable />
        </div>
      </section>

      {/* PRICING (real, DB-fed) */}
      <section className="tone-panel rail py-24">
        <PricingTeaser plans={plans} />
      </section>
    </div>
  );
}

