import Link from "next/link";
import type { Metadata } from "next";
import { db } from "@/lib/db";
import { Section, SectionTitle } from "@/components/marketing/primitives";
import { FeatureCard, CtaBand } from "@/components/marketing/sections";
import { Reveal } from "@/components/marketing/Reveal";
import { ReviewBadges } from "@/components/marketing/ReviewBadges";
import { Testimonials } from "@/components/marketing/Testimonials";
import { VibeCodingLanding, type PricePlan } from "@/components/marketing/aihostingtemplate/VibeCodingLanding";
import { IconSpark, IconBolt, IconArrow, IconCheck, IconUsers } from "@/components/marketing/icons";
import { FaqJsonLd } from "@/components/marketing/StructuredData";

// Plans + review badges read live DB state — render dynamically, matching the
// other DB-fed marketing pages (vps, business-email, domains).
export const dynamic = "force-dynamic";

export const metadata: Metadata = {
  title: "Vibe Coding — Build Websites & Apps With Claude Code",
  description:
    "Claude Code — the real Anthropic CLI — ships pre-installed on every Nxeon VPS. Describe the website or app you want in plain English and Claude writes it, runs it, and gets it live on your own server. Bring your Claude subscription or an API key; no separate plan to buy.",
  alternates: { canonical: "/vibe-coding" },
};

/** Format cents as a dollar string ("$6.49", "$12"). Matches /vps + /business-email. */
const money = (cents: number) => {
  const v = cents / 100;
  return Number.isInteger(v) ? `$${v}` : `$${v.toFixed(2)}`;
};

const BUILD = [
  {
    icon: <IconSpark />,
    title: "Launch a SaaS & make money",
    body: "Turn an idea into a real subscription product — sign-ups, a dashboard, Stripe payments. Charge users and watch it grow, all from a prompt.",
  },
  {
    icon: <IconUsers />,
    title: "Build a CRM for your business",
    body: "Track leads, customers, and deals your way — no $50/seat software. Ask Claude for exactly the fields and views your business runs on.",
  },
  {
    icon: <IconBolt />,
    title: "Get a website online today",
    body: "A polished site for your shop, restaurant, portfolio, or event — designed, built, and running on your server before lunch.",
  },
  {
    icon: <IconArrow />,
    title: "Automate the busywork",
    body: "Reports that email themselves, a bot that answers your Discord, a script that backs up your files nightly. Describe the chore; Claude handles it.",
  },
  {
    icon: <IconBolt />,
    title: "Build an internal tool",
    body: "An admin panel, an inventory tracker, a booking calendar for your team — the exact tool you wish existed, made to fit how you actually work.",
  },
  {
    icon: <IconSpark />,
    title: "Ship your app idea",
    body: "That app you've been meaning to build? Go from \"what if\" to a working MVP in an afternoon — and keep iterating just by asking for more.",
  },
];

const SAY_GET = [
  { say: "Build a modern landing page for my coffee shop with a menu and hours.", get: "A responsive site, running on your server." },
  { say: "Make me a client CRM with contacts, notes, and a deals pipeline.", get: "Your own CRM — no monthly per-seat fee." },
  { say: "Create a booking app so customers can reserve a time slot.", get: "A working scheduling app with a calendar." },
  { say: "Build a paid newsletter with Stripe subscriptions.", get: "A SaaS you can start charging for." },
];

const REASSURE = [
  "You never write or even see code unless you want to",
  "Claude explains everything in plain English",
  "Made a mistake? Just say \"undo that\" or \"change it to…\"",
  "It's your own server — you fully own everything you build",
];

const FAQ = [
  {
    q: "Do I need to install Claude Code myself?",
    a: "No. Every new Nxeon VPS ships with Claude Code pre-installed at first boot. If you're on a server from before this shipped, one command adds it (shown in your dashboard) — there's no reinstall or rebuild involved.",
  },
  {
    q: "Is there a separate \"vibe coding\" plan or price?",
    a: "No. This runs on the same VPS plans sold on /vps — there's no AI-hosting markup or separate tier. Pick the plan that fits your workload; Claude Code is included at every level.",
  },
  {
    q: "How do I pay for Claude usage?",
    a: "You bring your own Claude subscription (Pro or Max) or an Anthropic API key — Claude Code asks which the first time you run it. Either way, that's billed by Anthropic directly and is separate from your Nxeon invoice.",
  },
  {
    q: "Can I use Claude Code on my own computer instead?",
    a: "Yes — it's the same CLI either way. Running it on a Nxeon VPS mainly buys you a server that doesn't sleep when your laptop does, so long builds and always-on apps keep running.",
  },
  {
    q: "Does it deploy to a domain automatically?",
    a: "Claude runs and previews your app on your server. Pointing your own domain at it is a normal DNS step you do yourself — there's no automatic subdomain or certificate wizard bundled with this.",
  },
];

export default async function VibeCodingPage() {
  const dbPlans = await db.plan.findMany({ where: { active: true }, orderBy: { sortOrder: "asc" } });

  // Show up to 3 real plans (first, a popular middle pick, last) so the teaser
  // stays compact — full range + the interactive configurator live on /vps.
  const picks =
    dbPlans.length <= 3
      ? dbPlans
      : [dbPlans[0], dbPlans[Math.floor((dbPlans.length - 1) / 2)], dbPlans[dbPlans.length - 1]];
  const popularId = picks[Math.floor((picks.length - 1) / 2)]?.id;
  const plans: PricePlan[] = picks.map((p) => ({
    id: p.slug,
    tier: p.name,
    price: money(p.priceCents),
    ram: Math.round(p.ramMB / 1024),
    vcpu: p.cpuCores,
    nvme: p.diskGB,
    blurb: `${p.cpuCores} vCPU · ${p.diskGB} GB NVMe`,
    popular: p.id === popularId,
  }));

  return (
    <>
      <FaqJsonLd items={FAQ} />
      <VibeCodingLanding heroBadges={<ReviewBadges />} plans={plans} />

      {/* What will you build */}
      <Section size="lg">
        <SectionTitle
          eyebrow="What will you build?"
          title="Make money. Run your business. Ship your idea."
          sub="Vibe coding isn't a toy — it's how real people are launching products and replacing expensive software. Here's what you could start today."
        />
        <div className="mt-14 grid gap-6 sm:grid-cols-2 lg:grid-cols-3">
          {BUILD.map((b, i) => (
            <FeatureCard key={b.title} icon={b.icon} title={b.title} delay={i * 0.05}>
              {b.body}
            </FeatureCard>
          ))}
        </div>
      </Section>

      {/* Say this, get that */}
      <Section tone="light" size="lg">
        <SectionTitle
          eyebrow="Say this → get that"
          title="If you can describe it, you can build it"
          sub="Real prompts, real results. Copy one, change the details to fit your business, and paste it into Claude on your server."
        />
        <div className="mx-auto mt-12 grid max-w-4xl gap-4 sm:grid-cols-2">
          {SAY_GET.map((r) => (
            <Reveal key={r.say}>
              <div className="card flex h-full flex-col">
                <p className="text-[15px] font-medium leading-relaxed text-[var(--fg)]">&ldquo;{r.say}&rdquo;</p>
                <div className="mt-4 flex items-center gap-2 text-sm font-semibold text-emerald-700">
                  <IconArrow />
                  {r.get}
                </div>
              </div>
            </Reveal>
          ))}
        </div>
        <p className="mt-10 text-center">
          <Link href="/dashboard/claude-code" className="btn-secondary px-5 py-3 text-base">
            Browse 36 ready-made prompts
          </Link>
        </p>
      </Section>

      {/* Beginner friendly reassurance */}
      <Section tone="deep" size="lg">
        <div className="mx-auto max-w-2xl">
          <SectionTitle
            eyebrow="Beginner friendly"
            title="You don't need to be a developer"
            sub="If you can send an email, you can do this. Claude does the technical part — you just say what you want."
          />
          <ul className="mt-8 space-y-4">
            {REASSURE.map((r) => (
              <li key={r} className="flex items-start gap-3 text-lg text-slate-300">
                <span className="mt-1 flex-none text-emerald-400">
                  <IconCheck />
                </span>
                {r}
              </li>
            ))}
          </ul>
        </div>
      </Section>

      {/* Real social proof */}
      <Section tone="panel" size="lg">
        <SectionTitle eyebrow="Loved by makers" title="What people are building with it" />
        <div className="mt-12">
          {/* Async server component: renders real published testimonials when
              they exist, with an honestly-labelled illustrative fallback
              otherwise — same component used on the homepage. */}
          <Testimonials />
        </div>
      </Section>

      {/* FAQ */}
      <Section size="md">
        <SectionTitle eyebrow="FAQ" title="Questions, answered" />
        <div className="mx-auto mt-10 max-w-3xl space-y-4">
          {FAQ.map((f) => (
            <div key={f.q} className="card">
              <h3 className="text-base font-semibold text-white">{f.q}</h3>
              <p className="mt-2 text-sm leading-relaxed text-slate-400">{f.a}</p>
            </div>
          ))}
        </div>
      </Section>

      {/* Final CTA */}
      <Section tone="panel" size="lg">
        <CtaBand
          title="Your first build is one sentence away"
          sub="Every Nxeon VPS comes with Claude Code pre-installed. Deploy a server, run &quot;claude&quot;, and start describing what you want."
          primary={{ label: "See VPS plans", href: "/vps" }}
          secondary={{ label: "Browse prompts", href: "/dashboard/claude-code" }}
          note="Included on every server · No code needed · Bring your own Claude subscription or API key"
        />
      </Section>
    </>
  );
}
